<script setup lang="ts">
definePageMeta({layout:'workspace'})
const db=useSupabaseClient()
const {schoolId,schoolRole,platformAdmin,load:refreshSchools}=useSchool()
const allowed=computed(()=>platformAdmin.value||schoolRole.value==='school_admin')
const loading=ref(false),saving=ref(false),error=ref(''),notice=ref('')
const name=ref(''),code=ref(''),allowRegistration=ref(false),domains=ref<{domain:string;is_primary:boolean;is_verified:boolean}[]>([])
async function loadSettings(){if(!schoolId.value||!allowed.value)return;loading.value=true;error.value='';try{const [s,d]=await Promise.all([db.from('schools').select('name,code,allow_student_self_registration').eq('id',schoolId.value).single(),db.from('school_email_domains').select('domain,is_primary,is_verified').eq('school_id',schoolId.value).order('domain')]);if(s.error)throw s.error;if(d.error)throw d.error;name.value=s.data.name;code.value=s.data.code||'';allowRegistration.value=s.data.allow_student_self_registration;domains.value=d.data||[]}catch(e:any){error.value=e.message||'Unable to load school'}finally{loading.value=false}}
async function save(){if(!allowed.value||saving.value)return;saving.value=true;error.value='';notice.value='';try{const r=await db.rpc('update_school_settings',{p_school_id:schoolId.value,p_name:name.value,p_code:code.value,p_allow_student_registration:allowRegistration.value});if(r.error)throw r.error;await refreshSchools();notice.value='School settings saved'}catch(e:any){error.value=e.message||'Unable to save settings'}finally{saving.value=false}}
watch([schoolId,allowed],()=>{void loadSettings()},{immediate:true})
</script>
<template><div class="space-y-6"><h1 class="text-2xl font-bold">School settings</h1><UiPanel v-if="!allowed">School Administrator access is required.</UiPanel><UiPanel v-else><p v-if="loading">Loading school settings…</p><template v-else><p v-if="error" role="alert" class="mb-4 text-red-600">{{error}}</p><p v-if="notice" role="status" class="mb-4 text-green-600">{{notice}}</p><form class="max-w-xl space-y-5" @submit.prevent="save"><label class="block text-sm font-semibold">School name<input v-model="name" required minlength="2" maxlength="160" class="mt-2 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/></label><label class="block text-sm font-semibold">School code<input v-model="code" maxlength="30" class="mt-2 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/></label><label class="flex items-center gap-3 text-sm"><input v-model="allowRegistration" type="checkbox"/>Allow student self-registration</label><button type="submit" :disabled="saving" class="rounded-xl bg-blue-600 px-5 py-3 font-semibold text-white">{{saving?'Saving…':'Save settings'}}</button></form><h2 class="mt-8 mb-3 text-lg font-bold">School email domains</h2><p class="mb-3 text-sm text-[var(--muted)]">Domains are displayed for review. Verification and domain changes require the separate onboarding workflow.</p><div v-for="d in domains" :key="d.domain" class="flex flex-wrap justify-between gap-3 border-b border-[var(--border)] py-3 text-sm"><span>{{d.domain}}</span><span>{{d.is_verified?'Verified':'Not verified'}}{{d.is_primary?' · Primary':''}}</span></div><p v-if="!domains.length" class="text-sm text-[var(--muted)]">No school email domains configured.</p></template></UiPanel></div></template>